/* Quant Vault — local-first question bank. Data is stored in IndexedDB on this device. */
const DB_NAME='quant-vault-db', DB_VERSION=1, STORE='vault';
const defaultState={questions:[],chapters:[],syncMeta:{deletedQuestions:[],deletedChapters:[]},settings:{retainImages:true,syncImages:false,paper:'A4',orientation:'portrait',inside:30,outside:15,top:18,bottom:18,fontSize:11,lineSpacing:1.4,questionSpacing:4,chapterBreak:false,showStars:true,showIds:true,pageNumbers:true,mirrored:true,binding:'left',pdfStyle:'book'}};
let state=structuredClone(defaultState), db, page='dashboard', questionFilters={}, picked=new Set(), viewMode='cards', builderSelection=new Set(), builderQuestions=null, uploadedImage=null, editingQuestion=null;
let firebaseApi=null,firebaseAuth=null,firestore=null,storage=null,cloudUser=null,cloudState='Cloud sync is not configured',cloudBusy=false,cloudTimer=null;
let ocrLibraryPromise=null,ocrCdn='https://cdn.jsdelivr.net/npm';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
function loadOcrLibrary(){
  if(window.Tesseract?.createWorker)return Promise.resolve(window.Tesseract);
  if(ocrLibraryPromise)return ocrLibraryPromise;
  ocrLibraryPromise=(async()=>{
    const cdns=['https://cdn.jsdelivr.net/npm','https://unpkg.com'];
    let lastError;
    for(const cdn of cdns){
      try{
        await new Promise((resolve,reject)=>{
          const script=document.createElement('script');
          script.src=`${cdn}/tesseract.js@5/dist/tesseract.min.js`;
          script.async=true;
          script.onload=()=>resolve();
          script.onerror=()=>{script.remove();reject(new Error('Could not download the OCR library from the available file servers.'))};
          document.head.append(script);
        });
        if(!window.Tesseract?.createWorker)throw new Error('The OCR library loaded without its recognition interface.');
        ocrCdn=cdn;
        return window.Tesseract;
      }catch(error){lastError=error}
    }
    throw lastError||new Error('Could not load the OCR library.');
  })().catch(error=>{ocrLibraryPromise=null;throw error});
  return ocrLibraryPromise;
}
function formatOcrText(raw=''){
  const lines=String(raw).replace(/\f/g,'\n').split(/\r?\n/).map(line=>line.replace(/[|¦]/g,' ').replace(/[ \t]+/g,' ').trim());
  while(lines.length&&/^page(?:\s+\d+)?$/i.test(lines[lines.length-1]))lines.pop();
  const paragraphs=[];let current=[];
  for(const line of lines){if(!line){if(current.length)paragraphs.push(current.join(' '));current=[]}else current.push(line)}
  if(current.length)paragraphs.push(current.join(' '));
  let text=paragraphs.join('\n\n').replace(/\s+$/,'').replace(/\s+\bpage(?:\s+\d+)?\s*$/i,'');
  text=text.replace(/(^|[^\w/\\])(\d{1,4})\s*\/\s*(\d{1,4})(?![\w/])/g,(_,before,numerator,denominator)=>`${before}\\(\\frac{${numerator}}{${denominator}}\\)`);
  text=text.replace(/√\s*(\d{1,4})/g,'\\(\\sqrt{$1}\\)');
  const superscripts={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9'};
  text=text.replace(/([A-Za-z0-9)])([⁰¹²³⁴⁵⁶⁷⁸⁹]+)/g,(_,base,power)=>`\\(${base}^{${[...power].map(d=>superscripts[d]).join('')}}\\)`);
  return text;
}
function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>request.result.createObjectStore(STORE);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function readState(){return new Promise(resolve=>{const r=db.transaction(STORE).objectStore(STORE).get('state');r.onsuccess=()=>{const saved=r.result||{};resolve({...structuredClone(defaultState),...saved,settings:{...defaultState.settings,...saved.settings},syncMeta:{...defaultState.syncMeta,...saved.syncMeta}})};r.onerror=()=>resolve(structuredClone(defaultState))})}
function saveState(sync=true){return new Promise((resolve,reject)=>{if(sync)state.settingsUpdatedAt=Date.now();const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,'state');tx.oncomplete=()=>{resolve();if(sync)scheduleCloudSync()};tx.onerror=()=>reject(tx.error)})}
function toast(message,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3100)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtDate(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function updateCountdown(){const target=Date.UTC(2027,6,1),now=new Date(),today=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()),days=Math.ceil((target-today)/86400000),label=$('#countdownLabel');if(!label)return;label.textContent=days>0?`${days} days remaining · 01 Jul 2027`:days===0?'Today · 01 Jul 2027':'01 Jul 2027 passed';label.title='Countdown to July 1, 2027'}
function chapterName(id){return state.chapters.find(c=>c.id===id)?.name||'Unsorted'}
function shortQuestion(q){return q.text.trim().replace(/\s+/g,' ').slice(0,100)||'Untitled question'}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function makePrefix(name){const words=name.normalize('NFKD').replace(/[^a-zA-Z0-9 ]/g,' ').trim().split(/\s+/).filter(Boolean);return (words.length>1?words.map(x=>x[0]).join(''):words[0]?.slice(0,2)||'QV').toUpperCase().slice(0,4)}
function makeQid(chapterId){const prefix=makePrefix(chapterName(chapterId));const numbers=state.questions.map(q=>{const m=q.qid.match(new RegExp('^'+prefix+'-(\\d+)$'));return m?+m[1]:0});return `${prefix}-${String(Math.max(0,...numbers)+1).padStart(3,'0')}`}
function navTo(next){page=next;picked.clear();$('#sidebar').classList.remove('open');render()}
function chapterSelect(value='',includeAll=false){return `<select class="select" id="chapterFilter"><option value="">${includeAll?'All chapters':'Choose a chapter'}</option>${state.chapters.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`}
function questionCard(q,compact=false){return `<article class="question-card" data-qid="${esc(q.id)}"><div class="q-card-top"><span class="qid">${esc(q.qid)}</span><span class="tag">${esc(chapterName(q.chapterId))}</span>${q.topic?`<span class="tag">${esc(q.topic)}</span>`:''}<button class="star ${q.starred?'on':''}" data-star="${esc(q.id)}" aria-label="${q.starred?'Unstar':'Star'} question">${q.starred?'★':'☆'}</button></div><div class="question-text math-content">${esc(q.text)}</div><div class="q-card-bottom"><span class="q-meta">${q.source?esc(q.source)+' · ':''}${fmtDate(q.updatedAt||q.createdAt)}${q.remarks?' · Has remarks':''}</span><div class="q-actions"><button class="btn btn-outline btn-small" data-edit="${esc(q.id)}">Edit</button><button class="btn btn-outline btn-small" data-delete="${esc(q.id)}">Delete</button><button class="btn btn-outline btn-small" data-select="${esc(q.id)}">${picked.has(q.id)?'Selected':'Select'}</button></div></div></article>`}
function pageHead(title,desc,button=''){return `<div class="page-head"><div><p class="eyebrow">YOUR PRACTICE SPACE</p><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function render(){const labels={dashboard:'Dashboard',chapters:'My Chapters',questions:'All Questions',starred:'Starred Questions',add:'Add Question',builder:'PDF & Book Builder',settings:'Backup & Settings'};$('#pageCrumb').textContent=labels[page];$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('.mobile-nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const moreActive=['starred','builder','settings'].includes(page);$('#mobileMore')?.classList.toggle('active',moreActive);$('#chapterNavCount').textContent=state.chapters.length;$('#questionNavCount').textContent=state.questions.length;const root=$('#content');$('#connectionText').textContent=cloudUser?'Firebase sync is on':'Your data stays on this device';root.innerHTML=({dashboard:dashboardPage,chapters:chaptersPage,questions:()=>questionsPage(false),starred:()=>questionsPage(true),add:()=>questionFormPage(),builder:builderPage,settings:settingsPage}[page]||dashboardPage)();if(page==='settings')root.insertAdjacentHTML('afterbegin',cloudPanel()+pinSettingsPanel());bindPage();renderMath(root);root.querySelectorAll('.count-up').forEach(el=>{const value=+el.dataset.value;const start=performance.now();function tick(t){const p=Math.min(1,(t-start)/550);el.textContent=Math.round(value*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
function renderMath(root){if(!window.renderMathInElement)return;try{window.renderMathInElement(root,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:false,ignoredTags:['script','noscript','style','textarea','pre','code']})}catch(e){}}
function dashboardPage(){const qs=[...state.questions].sort((a,b)=>b.createdAt-a.createdAt),countWeek=qs.filter(q=>Date.now()-q.createdAt<7*864e5).length;const dist=state.chapters.map(c=>({c,n:qs.filter(q=>q.chapterId===c.id).length})).sort((a,b)=>b.n-a.n).slice(0,6);return `<section class="welcome"><div class="welcome-copy"><p class="eyebrow">A LITTLE PROGRESS, EVERY DAY</p><h1>Good to see you, question collector ✨</h1><p>Your next breakthrough is probably hiding in a question you saved.</p><button class="btn" data-go="add">＋ Capture a question</button></div><div class="welcome-art">📚</div></section><div class="stat-grid"><div class="stat-card"><div class="stat-top"><span class="stat-label">Questions collected</span><span class="stat-icon purple">▧</span></div><div class="stat-value count-up" data-value="${qs.length}">0</div><div class="stat-foot">Every tricky one, in one place</div></div><div class="stat-card"><div class="stat-top"><span class="stat-label">Your chapters</span><span class="stat-icon mint">▤</span></div><div class="stat-value count-up" data-value="${state.chapters.length}">0</div><div class="stat-foot">Organised your way</div></div><div class="stat-card"><div class="stat-top"><span class="stat-label">Starred for revision</span><span class="stat-icon yellow">★</span></div><div class="stat-value count-up" data-value="${qs.filter(q=>q.starred).length}">0</div><div class="stat-foot">The ones worth another look</div></div><div class="stat-card"><div class="stat-top"><span class="stat-label">Added this week</span><span class="stat-icon peach">✦</span></div><div class="stat-value count-up" data-value="${countWeek}">0</div><div class="stat-foot">Small steps add up</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Chapter collection</h2><span class="subtle">Question distribution</span></div>${dist.length?`<div class="chapter-bars">${dist.map(({c,n})=>`<div><div class="bar-label"><span>${esc(c.name)}</span><span>${n} question${n===1?'':'s'}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,n/Math.max(1,dist[0].n)*100)}%"></div></div></div>`).join('')}</div>`:`<div class="empty-state" style="padding:22px"><div class="empty-illustration">🗂️</div><h3>Your chapters start here</h3><p>Create chapters that match the way you study.</p><button class="btn btn-light" data-go="chapters">Create a chapter</button></div>`}<div class="quick-actions"><button class="quick-tile" data-go="chapters">＋ New chapter</button><button class="quick-tile" data-go="questions">▧ Browse questions</button><button class="quick-tile" data-go="builder">▤ Build a book</button></div></section><section class="panel"><div class="panel-head"><h2>Recently collected</h2><button class="btn btn-light btn-small" data-go="questions">See all →</button></div>${qs.length?`<div class="recent-list">${qs.slice(0,5).map(q=>`<div class="recent-row" data-edit="${esc(q.id)}"><span class="q-index">${esc(q.qid.slice(-3))}</span><span class="recent-info"><b>${esc(shortQuestion(q))}</b><small>${esc(chapterName(q.chapterId))} · ${fmtDate(q.createdAt)}</small></span><button class="star ${q.starred?'on':''}" data-star="${esc(q.id)}">${q.starred?'★':'☆'}</button></div>`).join('')}</div>`:`<div class="empty-state" style="padding:24px"><div class="empty-illustration">✍️</div><h3>No questions yet</h3><p>Save your first tricky question and it will show up here.</p><button class="btn btn-primary" data-go="add">Add a question</button></div>`}</section></div>`}
function chaptersPage(){return `${pageHead('My Chapters','Create a structure that fits your own preparation.','<button class="btn btn-primary" data-action="new-chapter">＋ New chapter</button>')}<div class="notice" style="margin-bottom:15px">Chapters are yours to name, rearrange, and reorganise. Questions keep their permanent IDs when you move them.</div>${state.chapters.length?`<div class="chapter-grid">${state.chapters.map((c,i)=>`<article class="chapter-card"><div class="chapter-card-head"><span class="chapter-dot">${['◈','⌁','✣','◇','▦'][i%5]}</span><span class="pill">${state.questions.filter(q=>q.chapterId===c.id).length} questions</span></div><h3>${esc(c.name)}</h3><p>${esc(c.description||'A space for your saved questions.')}</p><div class="chapter-card-foot"><span>${c.topics?.length||0} topics</span><div><button class="btn btn-outline btn-small" data-chapter-edit="${esc(c.id)}">Edit</button> <button class="btn btn-outline btn-small" data-chapter-up="${esc(c.id)}" ${i===0?'disabled':''}>↑</button> <button class="btn btn-outline btn-small" data-chapter-down="${esc(c.id)}" ${i===state.chapters.length-1?'disabled':''}>↓</button> <button class="btn btn-danger btn-small" data-chapter-delete="${esc(c.id)}">Delete</button></div></div></article>`).join('')}</div>`:`<div class="panel empty-state"><div class="empty-illustration">🗂️</div><h3>Set up your first chapter</h3><p>Start with any topic you like. No preset chapters, no rules.</p><button class="btn btn-primary" data-action="new-chapter">＋ Create a chapter</button></div>`}`}
function questionsPage(starOnly){let qs=state.questions.filter(q=>!starOnly||q.starred);const f=questionFilters[starOnly?'starred':'all']||{};const term=(f.term||'').toLowerCase();if(term)qs=qs.filter(q=>(q.qid+' '+q.text+' '+chapterName(q.chapterId)+' '+q.topic+' '+q.source).toLowerCase().includes(term));if(f.chapter)qs=qs.filter(q=>q.chapterId===f.chapter);if(f.topic)qs=qs.filter(q=>(q.topic||'').toLowerCase().includes(f.topic.toLowerCase()));if(f.recent==='added')qs=qs.filter(q=>Date.now()-q.createdAt<7*864e5);if(f.recent==='modified')qs=qs.filter(q=>Date.now()-q.updatedAt<7*864e5);qs.sort((a,b)=>f.sort==='oldest'?a.createdAt-b.createdAt:f.sort==='id'?a.qid.localeCompare(b.qid):b.createdAt-a.createdAt);const key=starOnly?'starred':'all';return `${pageHead(starOnly?'Starred Questions':'All Questions',starOnly?'Your personally important questions, ready for another look.':'Search, filter, and organise every question you have saved.',starOnly?'<button class="btn btn-primary" data-go="builder">Export starred →</button>':'<button class="btn btn-primary" data-go="add">＋ Add question</button>')}<div class="toolbar"><label class="search-box"><input class="input" id="questionSearch" placeholder="Search IDs, questions, chapters…" value="${esc(f.term||'')}" /></label>${chapterSelect(f.chapter||'',true)}<input class="input" id="topicFilter" placeholder="Topic" value="${esc(f.topic||'')}" style="width:115px"><select class="select" id="recentFilter"><option value="">Any time</option><option value="added" ${f.recent==='added'?'selected':''}>Added this week</option><option value="modified" ${f.recent==='modified'?'selected':''}>Modified this week</option></select><select class="select" id="sortFilter"><option value="newest">Newest first</option><option value="oldest" ${f.sort==='oldest'?'selected':''}>Oldest first</option><option value="id" ${f.sort==='id'?'selected':''}>Question ID</option></select><button class="btn btn-outline" id="viewToggle">${viewMode==='cards'?'☷ Compact':'▦ Cards'}</button></div>${picked.size?`<div class="toolbar"><span class="pill">${picked.size} selected</span><button class="btn btn-light btn-small" data-bulk="move">Move to chapter</button><button class="btn btn-danger btn-small" data-bulk="delete">Delete selected</button><button class="btn btn-outline btn-small" data-bulk="pdf">Export selected</button><button class="btn btn-outline btn-small" data-bulk="clear">Clear</button></div>`:''}${qs.length?`<div class="question-list ${viewMode==='compact'?'compact':''}">${qs.map(q=>questionCard(q)).join('')}</div>`:`<div class="panel empty-state"><div class="empty-illustration">${starOnly?'⭐':'🔎'}</div><h3>${starOnly?'No starred questions yet':'Nothing in this collection yet'}</h3><p>${starOnly?'Tap the star on any question to save it here.':'Add a question, then use search and filters to find it here.'}</p>${starOnly?'':`<button class="btn btn-primary" data-go="add">Add a question</button>`}</div>`}`}
function questionFormPage(){const q=editingQuestion;return `${pageHead(q?'Edit question':'Add a question',q?'Update the question details. Its ID stays permanent.':'Capture the question now; keep detailed solutions in your handwritten notebook.')}<div class="form-layout"><div class="form-stack"><div class="panel form-stack"><div class="field"><label for="qText">Question statement *</label><textarea id="qText" class="textarea" placeholder="Type or correct the question here. Mathematical notation such as x^2, √144, 3:5, and LaTeX commands stays editable.">${esc(q?.text||'')}</textarea><div class="field-help">Plain text and LaTeX-style notation are saved as editable text. Use LaTeX notation for fractions and square roots when helpful.</div></div><div class="field-row"><div class="field"><label>Chapter *</label><select id="qChapter" class="select" style="width:100%"><option value="">Choose a chapter</option>${state.chapters.map(c=>`<option value="${esc(c.id)}" ${c.id===q?.chapterId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Topic / subchapter</label><input id="qTopic" class="input" list="topicOptions" value="${esc(q?.topic||'')}" placeholder="Optional" style="width:100%"><datalist id="topicOptions">${[...new Set(state.chapters.flatMap(c=>c.topics||[]))].map(t=>`<option>${esc(t)}</option>`).join('')}</datalist></div></div><div class="field-row"><div class="field"><label>Source</label><input id="qSource" class="input" value="${esc(q?.source||'')}" placeholder="Book, mock test, coaching…" style="width:100%"></div><div class="field"><label>Personal remarks</label><input id="qRemarks" class="input" value="${esc(q?.remarks||'')}" placeholder="Optional reminder" style="width:100%"></div></div><label class="checkline"><input id="qStar" type="checkbox" ${q?.starred?'checked':''}> Star this question for revision</label><div style="display:flex;gap:8px"><button class="btn btn-primary" id="saveQuestion">${q?'Save changes':'Save question'}</button>${q?'<button class="btn btn-outline" data-action="cancel-edit">Cancel</button>':''}</div></div></div><div class="form-stack"><section class="panel"><div class="panel-head"><h2>Image to question</h2><span class="pill">OCR assist</span></div><div class="upload-zone" id="uploadZone"><div class="upload-icon">▧</div><b>Capture or upload an image</b><small>Camera or image file · PNG, JPG, WEBP</small><input type="file" id="imageUpload" class="file-hidden" accept="image/*" capture="environment"></div><img class="image-preview ${uploadedImage||q?.image?'':'hide'}" id="imagePreview" src="${uploadedImage||q?.image||''}" alt="Question source preview"><button class="btn btn-light btn-small ${uploadedImage||q?.image?'':'hide'}" id="runOcr" style="margin-top:9px">✦ Try text extraction</button><div id="ocrStatus" class="ocr-status"></div><div class="field-help" style="margin-top:12px">OCR removes stray divider marks and page labels, joins wrapped lines, and converts common fractions, roots, and powers to LaTeX. Mathematical OCR can still misread symbols, so review every result before saving.</div></section><section class="ocr-note"><b>Question bank, not solution notebook.</b><br>Only the question is stored here. Detailed working stays in your physical notebook and your permanent question ID links the two.</section></div></div>`}
function builderPage(){
  const ids=builderSelection,style=state.settings.pdfStyle||'book';
  return `${pageHead('PDF & Book Builder','Choose questions and create a chapter-organized book or a mixed exam paper.','<button class="btn btn-primary" id="generatePdf">▤ Preview & print PDF</button>')}<div class="builder-layout"><section class="panel"><div class="panel-head"><h2>Choose chapters and questions</h2><span class="subtle">${ids.size} selected</span></div><div class="toolbar"><button class="btn btn-outline btn-small" id="selectAllChapters">Select all chapters</button><button class="btn btn-outline btn-small" id="selectStarred">Select starred</button><button class="btn btn-outline btn-small" id="clearSelection">Clear</button></div>${state.chapters.length?`<div class="builder-list">${state.chapters.map(c=>{const qs=state.questions.filter(q=>q.chapterId===c.id);const all=qs.length>0&&qs.every(q=>ids.has(q.id));return `<div class="builder-row" style="background:#faf9ff"><input type="checkbox" data-chapter-check="${esc(c.id)}" ${all?'checked':''}><span style="flex:1"><b>${esc(c.name)}</b><small>${qs.length} questions</small></span></div>${qs.map(q=>`<div class="builder-row"><input type="checkbox" data-question-check="${esc(q.id)}" ${ids.has(q.id)?'checked':''}><span style="flex:1"><b>${esc(q.qid)} · ${esc(shortQuestion(q))}</b><small>${q.starred?'★ Starred · ':''}${q.topic?esc(q.topic):'No topic'}</small></span></div>`).join('')}`}).join('')}${state.questions.some(q=>!q.chapterId)?`<div class="builder-row"><b>Unsorted</b></div>${state.questions.filter(q=>!q.chapterId).map(q=>`<div class="builder-row"><input type="checkbox" data-question-check="${esc(q.id)}" ${ids.has(q.id)?'checked':''}><span><b>${esc(q.qid)} · ${esc(shortQuestion(q))}</b></span></div>`).join('')}`:''}</div>`:`<div class="empty-state"><div class="empty-illustration">📖</div><h3>Your book will grow here</h3><p>Add chapters and questions, then return to build your practice PDF.</p><button class="btn btn-light" data-go="add">Add a question</button></div>`}</section><aside class="panel"><div class="panel-head"><h2>Print settings</h2><span class="pill">${style==='exam'?'Exam paper':'Book layout'}</span></div><div class="builder-settings"><div class="field"><label>Document style</label><select class="select" id="settingStyle"><option value="book" ${style==='book'?'selected':''}>Study book · group by chapter</option><option value="exam" ${style==='exam'?'selected':''}>Exam paper · mix questions</option></select></div><div class="field"><label>Paper</label><select class="select" id="settingPaper"><option>A4</option><option ${state.settings.paper==='Letter'?'selected':''}>Letter</option></select></div><div class="field"><label>Orientation</label><select class="select" id="settingOrientation"><option value="portrait">Portrait</option><option value="landscape" ${state.settings.orientation==='landscape'?'selected':''}>Landscape</option></select></div><div class="field"><label>Inside margin (mm)</label><input class="input" type="number" min="10" max="60" id="settingInside" value="${state.settings.inside}"></div><div class="field"><label>Outside margin (mm)</label><input class="input" type="number" min="8" max="40" id="settingOutside" value="${state.settings.outside}"></div><div class="field"><label>Top / bottom (mm)</label><input class="input" type="number" min="8" max="40" id="settingTB" value="${state.settings.top}"></div><div class="field"><label>Font size (pt)</label><input class="input" type="number" min="8" max="16" id="settingFont" value="${state.settings.fontSize}"></div><div class="field"><label>Question gap (mm)</label><input class="input" type="number" min="2" max="20" id="settingGap" value="${state.settings.questionSpacing}"></div><div class="field"><label>Line spacing</label><input class="input" type="number" min="1" max="2" step=".05" id="settingLine" value="${state.settings.lineSpacing}"></div></div><div style="display:grid;gap:8px;margin-top:14px"><label class="checkline"><input type="checkbox" id="settingMirror" ${state.settings.mirrored?'checked':''}> Mirrored margins for binding</label><label class="checkline"><input type="checkbox" id="settingIds" ${state.settings.showIds?'checked':''}> Show permanent question IDs</label><label class="checkline"><input type="checkbox" id="settingStars" ${state.settings.showStars?'checked':''}> Show star marks</label><label class="checkline"><input type="checkbox" id="settingBreak" ${state.settings.chapterBreak?'checked':''}> Start each chapter on a new page</label><label class="checkline"><input type="checkbox" id="settingPages" ${state.settings.pageNumbers?'checked':''}> Show page numbers</label></div><div class="notice" style="margin-top:13px">PDF uses your browser’s print dialog. Choose “Save as PDF” to create the file. Exam paper mode removes chapter headings and shuffles selected questions.</div></aside></div>`
}
function settingsPage(){const size=state.questions.reduce((n,q)=>n+(q.image?.length||0)+q.text.length*2,0);return `${pageHead('Backup & Settings','Your collection stays on this device unless you connect Firebase.')}<div class="setting-grid"><section class="panel setting-item"><b>Backup your collection</b><p>Download chapters, questions, stars, IDs, settings, and retained image attachments as one JSON file.</p><div class="setting-row"><button class="btn btn-primary" id="exportBackup">↓ Download backup</button><label class="btn btn-outline" for="importBackup">↑ Restore backup</label><input class="file-hidden" id="importBackup" type="file" accept=".json,application/json"></div></section><section class="panel setting-item"><b>Storage on this device</b><p>Your question bank is saved privately in this browser using IndexedDB.</p><div class="setting-row"><span class="pill">${state.questions.length} questions</span><span class="pill">${state.chapters.length} chapters</span><span class="pill">~${(size/1024).toFixed(0)} KB text & images</span></div><div class="field-help" style="margin-top:9px">Browser data can be cleared by device cleanup. Download regular backups to keep a safe copy.</div></section><section class="panel setting-item"><b>Original image attachments</b><p>Choose whether uploaded image copies are retained with saved questions.</p><label class="checkline"><input type="checkbox" id="retainImages" ${state.settings.retainImages?'checked':''}> Keep source image with each question</label></section><section class="panel setting-item"><b>Privacy & offline use</b><p>By default, your collection stays in this browser. If you connect Firebase, saved questions sync privately to your account. App shell and local edits remain available offline once loaded.</p><span class="pill">Light theme · Local-first</span></section><section class="panel setting-item"><b>About mathematical OCR</b><p>Text extraction is an optional browser feature powered by Tesseract.js and requires internet the first time it loads. It recognises ordinary printed text, not math reliably. Inspect every extraction before saving. No OCR API key is used.</p><span class="pill">Manual correction required</span></section><section class="panel setting-item"><b>Clear this device</b><p>Delete the questions and chapters on this device; if signed in, deletions also sync to Firebase. Export a backup first if you might need them.</p><button class="btn btn-danger" id="clearData">Delete all local data</button></section></div>`}
function openModal(title,body,saveText='Save',onSave){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close-btn" data-modal-close>×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn btn-outline" data-modal-close>Cancel</button><button class="btn btn-primary" id="modalSave">${saveText}</button></div></section></div>`;root.onclick=e=>{if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-modal-close]')){root.innerHTML='';return}if(e.target.id==='modalSave')onSave?.()};setTimeout(()=>$('.modal input')?.focus(),50)}
let pinFailedAttempts=0,pinLockedUntil=0;
function bytesToBase64(bytes){return btoa(String.fromCharCode(...bytes))}
async function derivePinHash(pin,saltText){const salt=saltText?Uint8Array.from(atob(saltText),c=>c.charCodeAt(0)):crypto.getRandomValues(new Uint8Array(16));const saltB64=saltText||bytesToBase64(salt);const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:150000,hash:'SHA-256'},key,256);return{salt:saltB64,hash:bytesToBase64(new Uint8Array(bits))}}
function createPinDialog(afterSet){openModal('Create your 6-digit code',`<div class="field"><label>Choose a 6-digit code</label><input class="input pin-input" id="pinFirst" type="password" inputmode="numeric" maxlength="6" autocomplete="new-password" placeholder="••••••"></div><div class="field" style="margin-top:12px"><label>Enter it again</label><input class="input pin-input" id="pinConfirm" type="password" inputmode="numeric" maxlength="6" autocomplete="new-password" placeholder="••••••"></div><p class="pin-hint">This code is required before editing, moving, or deleting saved questions. It is stored as a salted hash and syncs with your Firebase settings. Keep it somewhere safe. If forgotten, reset it from Backup & Settings.</p>`,'Set code',async()=>{const a=$('#pinFirst').value,b=$('#pinConfirm').value;if(!/^\d{6}$/.test(a))return toast('Use exactly six digits.','error');if(a!==b)return toast('The two codes do not match.','error');if(!crypto.subtle)return toast('Secure code storage is unavailable in this browser. Open the app on localhost or HTTPS.','error');const result=await derivePinHash(a);state.settings.pinSalt=result.salt;state.settings.pinHash=result.hash;await saveState();$('#modalRoot').innerHTML='';toast('Verification code saved');afterSet?.()})}
function requirePin(action,callback){if(!state.settings.pinHash){createPinDialog(callback);return}if(Date.now()<pinLockedUntil){const seconds=Math.ceil((pinLockedUntil-Date.now())/1000);toast(`Try again in ${seconds} seconds.`,'error');return}openModal('Verify your code',`<p class="question-text">Enter your 6-digit code to ${esc(action)}.</p><input class="input pin-input" id="pinEntry" type="password" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="••••••"><p class="pin-hint" id="pinMessage">Five incorrect attempts pause verification for 30 seconds.</p>`,'Verify',async()=>{if(Date.now()<pinLockedUntil){$('#pinMessage').textContent=`Wait ${Math.ceil((pinLockedUntil-Date.now())/1000)} seconds before retrying.`;return}const value=$('#pinEntry').value;if(!/^\d{6}$/.test(value)){ $('#pinMessage').textContent='Enter all six digits.';return }const result=await derivePinHash(value,state.settings.pinSalt);if(result.hash!==state.settings.pinHash){pinFailedAttempts++;if(pinFailedAttempts>=5){pinFailedAttempts=0;pinLockedUntil=Date.now()+30000;$('#pinMessage').textContent='Too many incorrect attempts. Wait 30 seconds before retrying.'}else $('#pinMessage').textContent=`That code did not match. ${5-pinFailedAttempts} attempts left before a short pause.`;$('#pinEntry').value='';$('#pinEntry').focus();return}pinFailedAttempts=0;$('#modalRoot').innerHTML='';callback()})}
function openQuestionEditor(id){const q=state.questions.find(x=>x.id===id);if(!q)return;requirePin('edit this question',()=>{editingQuestion=q;uploadedImage=null;navTo('add')})}
function chapterModal(c){openModal(c?'Edit chapter':'Create a chapter',`<div class="form-stack"><div class="field"><label>Chapter name *</label><input class="input" id="chapterName" value="${esc(c?.name||'')}" placeholder="For example, Arithmetic" style="width:100%"></div><div class="field"><label>Description</label><input class="input" id="chapterDescription" value="${esc(c?.description||'')}" placeholder="Optional note about this chapter" style="width:100%"></div><div class="field"><label>Topics / subchapters</label><input class="input" id="chapterTopics" value="${esc((c?.topics||[]).join(', '))}" placeholder="Separate topics with commas" style="width:100%"><div class="field-help">Add optional topic names separated by commas. You can edit them later.</div></div></div>`,c?'Save changes':'Create chapter',async()=>{const name=$('#chapterName').value.trim();if(!name)return toast('Enter a chapter name first.','error');if(state.chapters.some(x=>x.id!==c?.id&&x.name.toLowerCase()===name.toLowerCase()))return toast('A chapter with that name already exists.','error');const now=Date.now(),val={id:c?.id||uid(),name,description:$('#chapterDescription').value.trim(),topics:$('#chapterTopics').value.split(',').map(x=>x.trim()).filter(Boolean),createdAt:c?.createdAt||now,updatedAt:now};if(c)state.chapters[state.chapters.findIndex(x=>x.id===c.id)]=val;else state.chapters.push(val);await saveState();$('#modalRoot').innerHTML='';toast(c?'Chapter updated':'Chapter created');render()})}
function addTombstone(type,id,at=Date.now()){const key=type==='question'?'deletedQuestions':'deletedChapters',list=state.syncMeta[key].filter(x=>x.id!==id);list.push({id,updatedAt:at});state.syncMeta[key]=list}
function deleteQuestion(id){const q=state.questions.find(x=>x.id===id);if(!q)return;requirePin('delete this question',()=>openModal('Delete question?',`<p class="question-text">Delete <b>${esc(q.qid)}</b> from your collection? This cannot be undone.</p>`,'Delete question',async()=>{state.questions=state.questions.filter(x=>x.id!==id);addTombstone('question',id);await saveState();$('#modalRoot').innerHTML='';toast('Question deleted');render()}))}
function bindPage(){ $$('[data-go]').forEach(b=>b.onclick=()=>navTo(b.dataset.go));$$('[data-star]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const q=state.questions.find(q=>q.id===b.dataset.star);if(q){q.starred=!q.starred;q.updatedAt=Date.now();await saveState();render();toast(q.starred?'Added to starred questions':'Removed from starred questions')}});$$('[data-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();openQuestionEditor(b.dataset.edit)});$$('[data-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteQuestion(b.dataset.delete)});$$('[data-select]').forEach(b=>b.onclick=()=>{picked.has(b.dataset.select)?picked.delete(b.dataset.select):picked.add(b.dataset.select);render()});$$('[data-action="new-chapter"]').forEach(b=>b.onclick=()=>chapterModal());$$('[data-chapter-edit]').forEach(b=>b.onclick=()=>chapterModal(state.chapters.find(c=>c.id===b.dataset.chapterEdit)));$$('[data-chapter-up]').forEach(b=>b.onclick=()=>moveChapter(b.dataset.chapterUp,-1));$$('[data-chapter-down]').forEach(b=>b.onclick=()=>moveChapter(b.dataset.chapterDown,1));$$('[data-chapter-delete]').forEach(b=>b.onclick=()=>deleteChapter(b.dataset.chapterDelete));$('#viewToggle')?.addEventListener('click',()=>{viewMode=viewMode==='cards'?'compact':'cards';render()});if(page==='questions'||page==='starred')bindFilters(page==='starred');if(page==='add')bindQuestionForm();if(page==='settings')bindSettings();if(page==='builder')bindBuilder() }
function deleteChapter(id){const c=state.chapters.find(x=>x.id===id),count=state.questions.filter(q=>q.chapterId===id).length;openModal('Delete this chapter?',`<p class="question-text">Delete <b>${esc(c.name)}</b>? ${count?`${count} saved question${count===1?'':'s'} will become unsorted. Their IDs and question text will stay intact.`:'This chapter has no questions.'}</p>`,'Delete chapter',async()=>{state.chapters=state.chapters.filter(x=>x.id!==id);addTombstone('chapter',id);state.questions.forEach(q=>{if(q.chapterId===id){q.chapterId=null;q.updatedAt=Date.now()}});await saveState();$('#modalRoot').innerHTML='';toast('Chapter deleted; saved questions kept');render()})}
async function moveChapter(id,by){const i=state.chapters.findIndex(c=>c.id===id),j=i+by;if(j<0||j>=state.chapters.length)return;[state.chapters[i],state.chapters[j]]=[state.chapters[j],state.chapters[i]];state.chapters.forEach(c=>c.updatedAt=Date.now());await saveState();render()}
function bindFilters(starOnly){const key=starOnly?'starred':'all';function apply(){questionFilters[key]={term:$('#questionSearch').value,chapter:$('#chapterFilter').value,topic:$('#topicFilter').value,recent:$('#recentFilter').value,sort:$('#sortFilter').value};render();const inp=$('#questionSearch');inp?.focus();inp?.setSelectionRange(inp.value.length,inp.value.length)}$('#questionSearch')?.addEventListener('input',()=>{clearTimeout(window.filterTimer);window.filterTimer=setTimeout(apply,150)});['chapterFilter','topicFilter','recentFilter','sortFilter'].forEach(id=>$('#'+id)?.addEventListener('change',apply));$$('[data-bulk]').forEach(b=>b.onclick=()=>bulkAction(b.dataset.bulk));}
function bulkAction(action){const ids=[...picked];if(action==='clear'){picked.clear();render();return}if(action==='pdf'){builderSelection=new Set(ids);navTo('builder');return}if(action==='move'){requirePin('move these questions',()=>{const opts=state.chapters.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');openModal('Move selected questions',`<div class="field"><label>New chapter</label><select id="bulkChapter" class="select" style="width:100%"><option value="">Choose a chapter</option>${opts}</select></div>`,'Move questions',async()=>{const cid=$('#bulkChapter').value;if(!cid)return toast('Choose a chapter first.','error');state.questions.forEach(q=>{if(picked.has(q.id)){q.chapterId=cid;q.updatedAt=Date.now()}});picked.clear();await saveState();$('#modalRoot').innerHTML='';toast(`${ids.length} questions moved; IDs unchanged`);render()})});return}if(action==='delete'){requirePin('delete these questions',()=>openModal('Delete selected questions?',`<p class="question-text">Delete ${ids.length} selected question${ids.length===1?'':'s'}? This cannot be undone.</p>`,'Delete questions',async()=>{ids.forEach(id=>addTombstone('question',id));state.questions=state.questions.filter(q=>!picked.has(q.id));picked.clear();await saveState();$('#modalRoot').innerHTML='';toast('Selected questions deleted');render()}))}}
function cloudReadyConfig(){const c=window.QUANT_VAULT_FIREBASE_CONFIG;return !!(c&&c.apiKey&&c.projectId&&c.appId&&!String(c.apiKey).startsWith('PASTE_'))}
function cloudPanel(){const setup=cloudReadyConfig();return `<section class="panel" style="margin-bottom:15px;border-color:#e5e1ff;background:linear-gradient(115deg,#fff 55%,#f8f5ff)"><div class="panel-head"><div><p class="eyebrow" style="margin-bottom:4px">CLOUD BACKUP & SYNC</p><h2 style="margin:0">Firebase connection</h2></div><span class="pill">${cloudUser?'Connected':setup?'Ready to connect':'Setup needed'}</span></div><p class="subtle" style="line-height:1.6;margin:0 0 13px">${cloudUser?`Signed in as ${esc(cloudUser.email||'your Firebase account')}. Saved questions sync when you are online.`:setup?'Sign in or create your private account to sync this collection across your devices.':'Add your Firebase web config to firebase-config.js, then refresh this app.'}</p><div class="setting-row" id="cloudActions">${!setup?'<span class="pill">No cloud project configured yet</span>':cloudUser?'<button class="btn btn-light btn-small" id="syncNow">↻ Sync now</button><button class="btn btn-outline btn-small" id="cloudSignOut">Sign out</button>':`<input class="input" id="cloudEmail" type="email" autocomplete="email" placeholder="Email address"><input class="input" id="cloudPassword" type="password" autocomplete="current-password" placeholder="Password"><button class="btn btn-primary" id="cloudSignIn">Sign in</button><button class="btn btn-outline btn-small" id="cloudSignUp">Create account</button>`}</div>${cloudUser?`<label class="checkline" style="margin-top:12px"><input type="checkbox" id="syncCloudImages" ${state.settings.syncImages?'checked':''}> Sync original images too (Firebase Storage; billing plan required)</label>`:``}<div class="field-help" id="cloudStatus" style="margin-top:10px">${esc(cloudState)}</div><div class="notice" style="margin-top:12px">Saved chapters, questions, settings, and deletion markers sync. Source images sync only if you turn that option on. OCR drafts and temporary previews stay on this device. Local saving continues if Firebase is offline.</div></section>`}
function pinSettingsPanel(){return `<section class="panel setting-item" style="margin-bottom:15px"><div class="panel-head"><div><p class="eyebrow" style="margin-bottom:4px">QUESTION SAFETY</p><h2 style="margin:0">Edit & delete code</h2></div><span class="pill">${state.settings.pinHash?'Code active':'Set on first use'}</span></div><p>This six-digit code is required before a saved question can be edited, moved, or deleted. It syncs with Firebase settings when connected.</p><div class="setting-row">${state.settings.pinHash?'<button class="btn btn-outline btn-small" id="changePin">Change code</button>':''}<button class="btn btn-light btn-small" id="resetPin">${state.settings.pinHash?'Reset forgotten code':'Create code now'}</button></div><p class="pin-hint">The code is hashed, not recoverable, and does not encrypt your question data. Resetting it keeps your questions; the next protected action will ask you to create a new code.</p></section>`}
function updateCloudStatus(message){cloudState=message;const el=$('#cloudStatus');if(el)el.textContent=message;const badge=$('#cloudConnectionBadge');if(badge)badge.textContent=cloudUser?'Firebase connected':'Local only'}
function scheduleCloudSync(){if(!cloudUser||!navigator.onLine)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>{if(cloudBusy){scheduleCloudSync();return}syncCloud().catch(e=>updateCloudStatus('Saved on this device; cloud sync will retry when online.'))},900)}
function cloudCollection(name){return firebaseApi.collection(firestore,'users',cloudUser.uid,name)}
function timestampOf(r){return Number(r?.updatedAt||r?.createdAt||0)}
function mergeRecordType(localRows,remoteDocs,tombstones,type){const tombKey=type==='questions'?'deletedQuestions':'deletedChapters';const localMap=new Map(localRows.map(x=>[x.id,{...x,deleted:false}]));for(const t of state.syncMeta[tombKey]){const prior=localMap.get(t.id);if(!prior||timestampOf(t)>=timestampOf(prior))localMap.set(t.id,{id:t.id,deleted:true,updatedAt:t.updatedAt||0})}const remoteMap=new Map(remoteDocs.docs.map(d=>[d.id,{...d.data(),id:d.id}]));const ids=new Set([...localMap.keys(),...remoteMap.keys()]);const active=[],tombs=[],uploads=[];for(const id of ids){const l=localMap.get(id),r=remoteMap.get(id);if(l&&(!r||timestampOf(l)>timestampOf(r))){if(l.deleted)tombs.push({id,updatedAt:timestampOf(l)});else{active.push(l);uploads.push(l)}}else if(r){if(r.deleted)tombs.push({id,updatedAt:timestampOf(r)});else{const merged={...r};if(type==='questions'&&l?.image&&!r.imagePath)merged.image=l.image;active.push(merged)}}}return{active,tombs,uploads}}
async function storeCloudRecord(type,row){const data={...row};delete data.deleted;if(type==='questions'){const image=data.image;delete data.image;const imagePath=data.imagePath||`users/${cloudUser.uid}/question-images/${row.id}`;if(state.settings.syncImages&&image?.startsWith('data:')){await firebaseApi.uploadString(firebaseApi.ref(storage,imagePath),image,'data_url');data.imagePath=imagePath;row.imagePath=imagePath}else if(!state.settings.syncImages){delete data.imagePath;if(row.imagePath)firebaseApi.deleteObject(firebaseApi.ref(storage,row.imagePath)).catch(()=>{})}}await firebaseApi.setDoc(firebaseApi.doc(firestore,'users',cloudUser.uid,type,row.id),data)}
async function hydrateCloudQuestion(q){if(state.settings.syncImages&&!q.image&&q.imagePath){try{const bytes=await firebaseApi.getBytes(firebaseApi.ref(storage,q.imagePath),12*1024*1024);const blob=new Blob([bytes]);q.image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}catch(e){/* Keep the question available even when an image download is unavailable. */}}return q}
async function syncCloud(){if(!cloudUser||cloudBusy||!navigator.onLine)return;cloudBusy=true;updateCloudStatus('Syncing your collection…');try{const [remoteChapters,remoteQuestions,remoteSettings]=await Promise.all([firebaseApi.getDocs(cloudCollection('chapters')),firebaseApi.getDocs(cloudCollection('questions')),firebaseApi.getDoc(firebaseApi.doc(firestore,'users',cloudUser.uid,'preferences','main'))]);const cm=mergeRecordType(state.chapters,remoteChapters,state.syncMeta.deletedChapters,'chapters');const qm=mergeRecordType(state.questions,remoteQuestions,state.syncMeta.deletedQuestions,'questions');for(let i=0;i<qm.active.length;i++)await hydrateCloudQuestion(qm.active[i]);state.chapters=cm.active;state.questions=qm.active;state.syncMeta={deletedChapters:cm.tombs,deletedQuestions:qm.tombs};for(const row of cm.uploads)await storeCloudRecord('chapters',row);for(const row of qm.uploads)await storeCloudRecord('questions',row);for(const t of cm.tombs)await firebaseApi.setDoc(firebaseApi.doc(firestore,'users',cloudUser.uid,'chapters',t.id),{id:t.id,deleted:true,updatedAt:t.updatedAt});for(const t of qm.tombs){await firebaseApi.setDoc(firebaseApi.doc(firestore,'users',cloudUser.uid,'questions',t.id),{id:t.id,deleted:true,updatedAt:t.updatedAt});if(state.settings.syncImages)firebaseApi.deleteObject(firebaseApi.ref(storage,`users/${cloudUser.uid}/question-images/${t.id}`)).catch(()=>{})}const cloudPrefs=remoteSettings.exists()?remoteSettings.data():null;const localPrefs={settings:state.settings,updatedAt:state.settingsUpdatedAt||0};if(cloudPrefs&&Number(cloudPrefs.updatedAt)>localPrefs.updatedAt){state.settings={...defaultState.settings,...cloudPrefs.settings};state.settingsUpdatedAt=Number(cloudPrefs.updatedAt)}else if(!cloudPrefs||localPrefs.updatedAt>Number(cloudPrefs.updatedAt||0)){await firebaseApi.setDoc(firebaseApi.doc(firestore,'users',cloudUser.uid,'preferences','main'),localPrefs)}await saveState(false);updateCloudStatus(`Synced just now · ${state.questions.length} questions, ${state.chapters.length} chapters`);if(page!=='settings')render()}catch(e){console.error('Firebase sync failed',e);updateCloudStatus('Cloud sync could not finish. Your local copy is safe; check your Firebase setup and connection.');throw e}finally{cloudBusy=false}}
async function initFirebase(){if(!cloudReadyConfig()){cloudState='Add the Firebase web config to firebase-config.js to enable cloud sync.';return}try{const v='13.4.0',base=`https://www.gstatic.com/firebasejs/${v}`;const [appM,authM,fireM,storageM]=await Promise.all([import(`${base}/firebase-app.js`),import(`${base}/firebase-auth.js`),import(`${base}/firebase-firestore.js`),import(`${base}/firebase-storage.js`)]);firebaseApi={...authM,...fireM,...storageM};const app=appM.initializeApp(window.QUANT_VAULT_FIREBASE_CONFIG);firebaseAuth=authM.getAuth(app);firestore=fireM.getFirestore(app);storage=storageM.getStorage(app);firebaseApi.onAuthStateChanged(firebaseAuth,user=>{cloudUser=user;updateCloudStatus(user?'Connected. Checking for changes…':'Firebase ready. Sign in to sync this device.');if(page==='settings')render();if(user)syncCloud().catch(()=>{})});window.addEventListener('online',()=>{if(cloudUser)syncCloud().catch(()=>{})});cloudState='Firebase is ready. Sign in to sync this device.'}catch(e){console.error('Firebase initialization failed',e);cloudState='Firebase could not initialize. Check the web config and internet connection.'}}
function bindQuestionForm(){const input=$('#imageUpload'),zone=$('#uploadZone');zone?.addEventListener('click',e=>{if(e.target!==input)input.click()});input?.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{uploadedImage=reader.result;const img=$('#imagePreview');img.src=uploadedImage;img.classList.remove('hide');$('#runOcr').classList.remove('hide');$('#ocrStatus').textContent='Image ready. Select “Try text extraction” to run OCR.'};reader.readAsDataURL(file)});$('#runOcr')?.addEventListener('click',runOcr);$('#saveQuestion')?.addEventListener('click',saveQuestionForm);$('#qText')?.focus()}
async function saveQuestionForm(){const text=$('#qText').value.trim(),chapterId=$('#qChapter').value;if(!text)return toast('Add the question statement before saving.','error');if(!chapterId||!state.chapters.some(c=>c.id===chapterId))return toast('Create or select a chapter first.','error');const now=Date.now(),prev=editingQuestion;const q={id:prev?.id||uid(),qid:prev?.qid||makeQid(chapterId),text,chapterId,topic:$('#qTopic').value.trim(),starred:$('#qStar').checked,source:$('#qSource').value.trim(),remarks:$('#qRemarks').value.trim(),createdAt:prev?.createdAt||now,updatedAt:now,imagePath:prev?.imagePath||null,image:state.settings.retainImages?(uploadedImage||prev?.image||null):null};if(prev)state.questions[state.questions.findIndex(x=>x.id===prev.id)]=q;else state.questions.push(q);await saveState();editingQuestion=null;uploadedImage=null;toast(prev?'Question updated · ID preserved':`Question saved · ${q.qid}`);navTo('questions')}
async function runOcr(){
  const uploadedForOcr=Boolean(uploadedImage),image=uploadedImage||editingQuestion?.image;if(!image)return;
  const status=$('#ocrStatus'),button=$('#runOcr');
  if(button)button.disabled=true;
  let worker;
  try{
    status.textContent='Loading the text recognition engine…';
    const {createWorker}=await loadOcrLibrary();
    status.textContent='Preparing English text recognition…';
    worker=await createWorker('eng',1,{
      workerPath:`${ocrCdn}/tesseract.js@5/dist/worker.min.js`,
      corePath:`${ocrCdn}/tesseract.js-core@5`,
      langPath:'https://tessdata.projectnaptha.com/4.0.0',
      logger:m=>{
        if(m.status==='loading tesseract core')status.textContent='Loading the OCR engine…';
        else if(m.status==='initializing tesseract')status.textContent='Starting text recognition…';
        else if(m.status==='loading language traineddata')status.textContent='Downloading English text data…';
        else if(m.status==='initializing api')status.textContent='Preparing the image…';
        else if(m.status==='recognizing text')status.textContent=`Reading text… ${Math.round((m.progress||0)*100)}%`;
      }
    });
    const result=await worker.recognize(image);
    const extracted=formatOcrText(result.data.text||'');
    if(!extracted)throw new Error('No printed text was detected. Try a sharper, brighter image or type the question manually.');
    $('#qText').value=extracted;
    status.textContent='Text extracted and cleaned. Common fractions, roots, and powers use LaTeX; review all math and wording before saving.';
    toast('Text extraction complete. Please review it.');
  }catch(e){
    console.error('OCR failed',e);
    const reason=String(e?.message||e||'').replace(/https?:\/\/\S+/g,'OCR service file').slice(0,180);
    status.textContent=reason?`Text extraction could not finish: ${reason}. Check your internet connection and try again, or type the question manually.`:'Text extraction could not finish. Check your internet connection and try again, or type the question manually.';
    toast('Text extraction could not finish.','error');
  }finally{
    if(worker)try{await worker.terminate()}catch(e){console.warn('OCR worker cleanup failed',e)}
    if(uploadedForOcr){
      uploadedImage=null;
      const preview=$('#imagePreview'),input=$('#imageUpload');
      if(preview){preview.removeAttribute('src');preview.classList.add('hide')}
      if(input)input.value='';
      if(button)button.classList.add('hide');
      status.textContent+=' Source image cleared from this device.';
    }
    if(button)button.disabled=false;
  }
}
function bindSettings(){$('#exportBackup').onclick=exportBackup;$('#importBackup').onchange=importBackup;$('#retainImages').onchange=async e=>{state.settings.retainImages=e.target.checked;await saveState();toast('Image preference saved')};$('#clearData').onclick=()=>openModal('Delete all local data?',`<p class="question-text">This permanently removes all ${state.questions.length} questions and ${state.chapters.length} chapters from this device and, when signed in, your synced collection. Download a backup first if needed.</p>`,'Delete everything',async()=>{const now=Date.now(),deletedQuestions=[...state.syncMeta.deletedQuestions,...state.questions.map(q=>({id:q.id,updatedAt:now}))],deletedChapters=[...state.syncMeta.deletedChapters,...state.chapters.map(c=>({id:c.id,updatedAt:now}))];state=structuredClone(defaultState);state.syncMeta={deletedQuestions,deletedChapters};state.settingsUpdatedAt=now;await saveState();$('#modalRoot').innerHTML='';toast('Local collection cleared');navTo('dashboard')});bindCloudPanel();bindPinSettings()}
function friendlyAuthError(e){const c=e?.code||'';return({'auth/invalid-credential':'Email or password was not accepted.','auth/email-already-in-use':'An account already uses this email. Try signing in.','auth/weak-password':'Choose a longer password.','auth/invalid-email':'Enter a valid email address.','auth/too-many-requests':'Too many attempts. Wait a little and try again.','auth/operation-not-allowed':'Enable Email/Password sign-in in Firebase Authentication.','permission-denied':'Firebase denied access. Check that the Firestore rules are installed.','storage/unauthorized':'Firebase denied image access. Check the Storage rules.'}[c]||e?.message||'Firebase could not complete that action.')}
function bindCloudPanel(){if(!cloudReadyConfig())return;$('#cloudSignIn')?.addEventListener('click',async()=>{const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value;if(!email||!password)return updateCloudStatus('Enter your email and password first.');try{updateCloudStatus('Signing in…');await firebaseApi.signInWithEmailAndPassword(firebaseAuth,email,password)}catch(e){updateCloudStatus(friendlyAuthError(e))}});$('#cloudSignUp')?.addEventListener('click',async()=>{const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value;if(!email||!password)return updateCloudStatus('Enter your email and password first.');try{updateCloudStatus('Creating your account…');await firebaseApi.createUserWithEmailAndPassword(firebaseAuth,email,password)}catch(e){updateCloudStatus(friendlyAuthError(e))}});$('#cloudSignOut')?.addEventListener('click',async()=>{await firebaseApi.signOut(firebaseAuth);cloudUser=null;updateCloudStatus('Signed out. Your local data is still here.');render()});$('#syncNow')?.addEventListener('click',()=>syncCloud().then(()=>toast('Firebase sync complete')).catch(()=>toast('Local copy is safe; cloud sync needs attention.','error')));$('#syncCloudImages')?.addEventListener('change',async e=>{state.settings.syncImages=e.target.checked;state.questions.forEach(q=>q.updatedAt=Date.now());await saveState();toast(e.target.checked?'Image sync enabled':'Image sync disabled')})}
function bindPinSettings(){$('#changePin')?.addEventListener('click',()=>requirePin('change your code',()=>createPinDialog(()=>render())));$('#resetPin')?.addEventListener('click',()=>{if(!state.settings.pinHash){createPinDialog(()=>render());return}openModal('Reset your code?',`<p class="question-text">This removes only the existing code. Your questions stay safe. The next edit, move, or delete will require you to create a new six-digit code.</p>`,'Reset code',async()=>{delete state.settings.pinHash;delete state.settings.pinSalt;await saveState();$('#modalRoot').innerHTML='';toast('Code reset. Create a new one on first use.');render()})})}
function exportBackup(){const blob=new Blob([JSON.stringify({format:'QuantVaultBackup',version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});downloadBlob(blob,`quant-vault-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Backup downloaded')}
function importBackup(e){const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=async()=>{try{const d=JSON.parse(reader.result);if(d.format!=='QuantVaultBackup'||!Array.isArray(d.questions)||!Array.isArray(d.chapters))throw Error('Not a Quant Vault backup');openModal('Restore this backup?',`<p class="question-text">This backup contains <b>${d.questions.length} questions</b> and <b>${d.chapters.length} chapters</b>. Restoring replaces the current collection on this device.</p>`,'Restore backup',async()=>{state={...structuredClone(defaultState),...d,settings:{...defaultState.settings,...d.settings}};await saveState();$('#modalRoot').innerHTML='';toast('Backup restored');navTo('dashboard')})}catch(err){toast('That file is not a valid Quant Vault backup.','error')}e.target.value=''};reader.readAsText(f)}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bindBuilder(){const settings=state.settings;$('#selectAllChapters')?.addEventListener('click',()=>{state.chapters.forEach(c=>state.questions.filter(q=>q.chapterId===c.id).forEach(q=>builderSelection.add(q.id)));render()});$('#selectStarred')?.addEventListener('click',()=>{state.questions.filter(q=>q.starred).forEach(q=>builderSelection.add(q.id));render()});$('#clearSelection')?.addEventListener('click',()=>{builderSelection.clear();render()});$$('[data-question-check]').forEach(c=>c.onchange=()=>{c.checked?builderSelection.add(c.dataset.questionCheck):builderSelection.delete(c.dataset.questionCheck);render()});$$('[data-chapter-check]').forEach(c=>c.onchange=()=>{state.questions.filter(q=>q.chapterId===c.dataset.chapterCheck).forEach(q=>c.checked?builderSelection.add(q.id):builderSelection.delete(q.id));render()});['settingStyle','settingPaper','settingOrientation','settingInside','settingOutside','settingTB','settingFont','settingGap','settingLine','settingMirror','settingIds','settingStars','settingBreak','settingPages'].forEach(id=>$('#'+id)?.addEventListener('change',()=>{settings.pdfStyle=$('#settingStyle').value;settings.paper=$('#settingPaper').value;settings.orientation=$('#settingOrientation').value;settings.inside=+$('#settingInside').value;settings.outside=+$('#settingOutside').value;settings.top=+$('#settingTB').value;settings.bottom=settings.top;settings.fontSize=+$('#settingFont').value;settings.questionSpacing=+$('#settingGap').value;settings.lineSpacing=+$('#settingLine').value;settings.mirrored=$('#settingMirror').checked;settings.showIds=$('#settingIds').checked;settings.showStars=$('#settingStars').checked;settings.chapterBreak=$('#settingBreak').checked;settings.pageNumbers=$('#settingPages').checked;saveState()}));$('#generatePdf')?.addEventListener('click',generatePdf)}
function generatePdf(){
  let selected=builderSelection.size?state.questions.filter(q=>builderSelection.has(q.id)):[];
  if(!selected.length)return toast('Select at least one question to build your PDF.','error');
  const s=state.settings,exam=s.pdfStyle==='exam';
  if(exam){for(let i=selected.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[selected[i],selected[j]]=[selected[j],selected[i]]}}
  const ordered=[];
  state.chapters.forEach(c=>{const qs=selected.filter(q=>q.chapterId===c.id);if(qs.length)ordered.push({name:c.name,qs})});
  const unsorted=selected.filter(q=>!q.chapterId);if(unsorted.length)ordered.push({name:'Unsorted',qs:unsorted});
  const inside=s.mirrored?s.inside:s.outside;
  const questionHtml=q=>`<div class="print-q">${s.showIds?`<b class="qid-print">${esc(q.qid)}</b> `:''}${s.showStars&&q.starred?'<span class="star-print">★ </span>':''}<span class="question-body">${esc(formatOcrText(q.text)).replace(/\n/g,'<br>')}</span></div>`;
  const examHtml=exam?`<h1>Quantitative Aptitude<br><small>Practice Exam</small></h1><div class="exam-meta"><span>Name: ____________________</span><span>Date: ______________</span><span>Score: ____ / ${selected.length}</span></div><p class="exam-date">Generated ${new Date().toLocaleDateString()}</p><section class="exam-questions">${selected.map(q=>questionHtml(q)).join('')}</section>`:'';
  const coverHtml=`<section class="book-cover"><div class="cover-top"><span class="cover-mark">QV</span><span class="cover-brand"><b>QUANT VAULT</b><small>PERSONAL PRACTICE SERIES</small></span></div><svg class="cover-art" viewBox="0 0 240 190" aria-hidden="true"><path d="M18 45c31-14 62-11 101 8v111c-36-19-70-22-101-8zM119 53c39-19 72-22 103-8v111c-31-14-65-11-103 8z"/><path d="M34 68c22-7 43-5 65 5M34 89c22-7 43-5 65 5M34 110c22-7 43-5 65 5M139 73c23-10 46-12 67-5M139 94c23-10 46-12 67-5M139 115c23-10 46-12 67-5"/><path d="M119 53v111"/><circle cx="202" cy="33" r="11"/><path d="M178 25h-38M202 9v-7M225 33h13M187 18l-7-7M218 18l7-7"/></svg><div class="cover-copy"><p class="cover-kicker">BUILDING SKILL, ONE QUESTION AT A TIME</p><h1 class="cover-title">Quantitative<br>Aptitude<br><span>Question Bank</span></h1><p class="cover-subtitle">A focused collection for practice, revision, and steady progress.</p></div><div class="cover-bottom"><div class="cover-stats"><span><b>${selected.length}</b><small>QUESTIONS</small></span><span><b>${ordered.length}</b><small>CHAPTERS</small></span></div><div class="cover-footer"><span>PREPARED FOR ______________________________</span><span>${new Date().toLocaleDateString()}</span></div></div></section><div class="book-content"><h1>Quantitative Aptitude Question Bank</h1><div class="book-meta">Quant Vault · ${selected.length} questions · ${new Date().toLocaleDateString()}</div>${ordered.map((c,i)=>`<section class="chapter ${i===0?'first-chapter':''}"><h2>${esc(c.name)}</h2>${c.qs.map(q=>questionHtml(q)).join('')}</section>`).join('')}</div>`;
  const bookHtml=coverHtml;
  const html=`<div class="print-book ${exam?'exam-paper':''}" style="--print-size:${s.fontSize}pt;--print-leading:${s.lineSpacing};--q-space:${s.questionSpacing}mm;--top-margin:${s.top}mm;--bottom-margin:${s.bottom}mm;--inside-margin:${inside}mm;--outside-margin:${s.outside}mm;--paper-size:${s.paper};--paper-orientation:${s.orientation};--chapter-break:${s.chapterBreak?'page':'auto'}">${exam?examHtml:bookHtml}</div>`;
  const root=$('#content');$('#connectionText').textContent=cloudUser?'Firebase sync is on':'Your data stays on this device';
  const title=exam?'Your mixed exam paper':'Your practice book',description=exam?`${selected.length} questions mixed across your selection · No chapter names are printed.`:`${selected.length} questions across ${ordered.length} chapters · Use the print dialog to save a PDF.`;
  root.innerHTML=`<div class="page-head no-print"><div><p class="eyebrow">PDF PREVIEW</p><h1>${title}</h1><p>${description}</p></div><button class="btn btn-primary" id="printNow">Print / Save as PDF</button></div><div class="panel no-print" style="margin-bottom:15px"><b style="font-size:11px">Review your selection before printing.</b> <button class="btn btn-light btn-small" id="returnBuilder">← Back to builder</button></div>${html}`;
  const pageNumberRule=s.pageNumbers?'@bottom-center{content:counter(page);font:8pt Arial,sans-serif;color:#444}':'';
  const firstPageNumberRule=s.pageNumbers?'@bottom-center{content:""}':'';
  const dynamicPrintStyle=document.createElement('style');dynamicPrintStyle.id='dynamicPrintStyle';dynamicPrintStyle.textContent=`@media print{@page{size:${s.paper} ${s.orientation};margin-top:${s.top}mm;margin-bottom:${s.bottom}mm;${pageNumberRule}}@page :right{margin-left:${inside}mm;margin-right:${s.outside}mm}@page :left{margin-left:${s.outside}mm;margin-right:${inside}mm}@page:first{margin:0;${firstPageNumberRule}}}`;$('#dynamicPrintStyle')?.remove();document.head.append(dynamicPrintStyle);
  renderMath(root);$('#printNow').onclick=()=>window.print();$('#returnBuilder').onclick=()=>navTo('builder');
}
function bindGlobal(){$$('.nav-item[data-page]').forEach(b=>b.onclick=()=>navTo(b.dataset.page));$$('.mobile-nav-item[data-page]').forEach(b=>b.onclick=()=>navTo(b.dataset.page));$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#mobileMore').onclick=()=>$('#sidebar').classList.toggle('open');$('#drawerScrim').onclick=()=>$('#sidebar').classList.remove('open');document.addEventListener('click',e=>{const star=e.target.closest('[data-star]');if(star)return;const card=e.target.closest('.recent-row');if(card&&e.target===card){const q=state.questions.find(q=>q.id===card.dataset.edit);if(q)openQuestionEditor(q.id)}});}
